// Waveshare 4.3B — DI0 isolated input (EXIO0) bring-up.
// Field side energized -> optocoupler pulls the expander bit LOW.
#include <Wire.h>
#define CH422G_RD_IO 0x26      // input read (EXIO0..7)
#define ISO_IN_DI0   (1 << 0)  // EXIO0

bool di0_active() {
  Wire.requestFrom(CH422G_RD_IO, 1);
  uint8_t bits = Wire.read();
  return (bits & ISO_IN_DI0) == 0;  // active-LOW when energized
}

