code.DO0:
// Waveshare 4.3B — DO0 isolated open-drain output (OD0).
// Bit LOW conducts (sinks the load); HIGH releases it. VERIFY polarity.
#include <Wire.h>
#define CH422G_WR_OC 0x23       // open-drain latch (OD0..3)
#define ISO_OUT_DO0  (1 << 0)   // OD0

void do0_pulse_ms(uint16_t ms) {
  Wire.beginTransmission(CH422G_WR_OC);
  Wire.write((uint8_t)~ISO_OUT_DO0 & 0x0F);  // sink DO0
  Wire.endTransmission();
  delay(ms);                                    // bounded pulse
  Wire.beginTransmission(CH422G_WR_OC);
  Wire.write(0x0F);                             // release all
  Wire.endTransmission();
}

