code.50 mm:
// VL53L0X time-of-flight (I2C 0x29). Continuous ranging, mm.
// Full init in playground.cpp tof_init(); the read is:
#include <Wire.h>
#define VL53L0X 0x29

bool tof_read_mm(uint16_t* mm) {
  uint8_t status = 0;
  Wire.beginTransmission(VL53L0X); Wire.write(0x13);
  Wire.endTransmission(false); Wire.requestFrom(VL53L0X, 1);
  status = Wire.read();
  if (!(status & 0x07)) return false;         // no new sample
  uint8_t r[2];
  Wire.beginTransmission(VL53L0X); Wire.write(0x1E);
  Wire.endTransmission(false); Wire.requestFrom(VL53L0X, 2);
  r[0] = Wire.read(); r[1] = Wire.read();
  *mm = (r[0] << 8) | r[1];
  Wire.beginTransmission(VL53L0X); Wire.write(0x0B); Wire.write(0x01);
  Wire.endTransmission();                      // clear interrupt
  return true;
}

