// MPR121 12-electrode cap-touch (I2C 0x5A). Read the touch bitmap.
#include <Wire.h>
#define MPR121 0x5A

uint16_t pad_touched() {
  uint8_t b[2];
  Wire.beginTransmission(MPR121); Wire.write(0x00);
  Wire.endTransmission(false); Wire.requestFrom(MPR121, 2);
  b[0] = Wire.read(); b[1] = Wire.read();
  return (b[0] | (b[1] << 8)) & 0x0FFF;   // electrodes 0..11
}

