// I2C census — scan the shared 8/9 bus (playground.cpp census()).
#include <Wire.h>

void i2c_census() {
  for (uint8_t a = 0x08; a <= 0x77; a++) {
    Wire.beginTransmission(a);
    if (Wire.endTransmission() == 0) Serial.printf("  0x%02X\n", a);
  }
}
